    if (estimated == NULL || target == NULL || error == NULL) {
        if (error != NULL) {
            error->x = 0.0;
            error->y = 0.0;
            error->z = 0.0;
        }
        return ADCS_E_NULL;
    }

    if (!isfinite(estimated->x) || !isfinite(estimated->y) || !isfinite(estimated->z) || !isfinite(estimated->w) ||
        !isfinite(target->x) || !isfinite(target->y) || !isfinite(target->z) || !isfinite(target->w)) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t norm_est, norm_tgt;
    if (adcs_quat_normalize(estimated, &norm_est) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_quat_normalize(target, &norm_tgt) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t q_err_conj = adcs_quat_conjugate(&norm_est);
    adcs_quat_t q_err = adcs_quat_multiply(&norm_tgt, &q_err_conj);

    if (q_err.w < 0.0) {
        q_err.w = -q_err.w;
        q_err.x = -q_err.x;
        q_err.y = -q_err.y;
        q_err.z = -q_err.z;
    }

    double s = sqrt(q_err.x * q_err.x + q_err.y * q_err.y + q_err.z * q_err.z);

    if (s <= 1e-12) {
        error->x = 2.0 * q_err.x;
        error->y = 2.0 * q_err.y;
        error->z = 2.0 * q_err.z;
    } else {
        double angle = 2.0 * atan2(s, q_err.w);
        double scale = angle / s;
        error->x = scale * q_err.x;
        error->y = scale * q_err.y;
        error->z = scale * q_err.z;
    }

    return ADCS_OK;
}

