    double s = sqrt(q_error.x * q_error.x + q_error.y * q_error.y + q_error.z * q_error.z);

    // Convert to rotation vector
    if (s <= ADCS_EPS_NORM) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
    } else {
        double angle = 2.0 * atan2(s, q_error.w);
        double scale = angle / s;
        error->x = scale * q_error.x;
        error->y = scale * q_error.y;
        error->z = scale * q_error.z;
    }

    return ADCS_OK;
